export type 小游戏种类 = '出餐顺序' | '搬料配重' | '分拣' | '送货路线';

export type 活的规格 = {
  /** 一次活的时长，按游戏内时段计。 */
  时长: number;
  /** 基础时薪。结算时按表现与熟练度乘开。 */
  时薪: number;
  /** 一次活消耗的哥哥体力。 */
  体力: number;
  /** 小游戏类型，决定面板里玩哪一个。 */
  玩法: 小游戏种类;
  /** 小游戏一轮几题。题越多，得分越细。 */
  题数: number;
  /** 一句话说明这份活具体做什么，显示在活的名字下面。 */
  说明: string;
};

