/** 熟练度四档。改门槛就同时改了面板上的档位名与结算倍率。 */
export const 熟练档表 = [
  { 名: '生手', 门槛: 20, 倍率: 1 },
  { 名: '上手', 门槛: 45, 倍率: 1.15 },
  { 名: '熟手', 门槛: 75, 倍率: 1.3 },
  { 名: '老手', 门槛: 100, 倍率: 1.5 },
];

export function 取熟练档(值: unknown) {
  const 数 = Number(值);
  const 钳 = Number.isFinite(数) ? Math.max(0, Math.min(100, 数)) : 0;
  return 熟练档表.find(档 => 钳 < 档.门槛) ?? 熟练档表[熟练档表.length - 1];
}

/** 体力低于这条线，收入打折。正文里也该写出他撑不住。 */
export const 疲劳阈值 = 30;

/** 表现分（0~100）映射到收入倍率（0.6~1.6）。 */
export function 表现倍率(分: number) {
  const 钳 = Math.max(0, Math.min(100, 分));
  return Number((0.6 + (钳 / 100) * 1.0).toFixed(2));
}

export type 结算结果 = {
  收入: number;
  表现倍率: number;
  熟练倍率: number;
  疲劳折扣: number;
  体能变化: number;
  熟练变化: number;
};

/**
 * 一次打工的结算。纯函数，面板与脚本都调它，保证两边算出来的数一样。
 * `体力` 是结算前的体力，`熟练` 是结算前的熟练度。
 */
export function 结算打工(参数: {
  时薪: number;
  题数: number;
  得分: number;
  体力: number;
  熟练: number;
  原有体力消耗: number;
}): 结算结果 {
  const 表现 = 表现倍率(参数.得分);
  const 熟练 = 取熟练档(参数.熟练);
  const 折扣 = 参数.体力 < 疲劳阈值 ? 0.75 : 1;
  const 收入 = Math.max(0, Math.round(参数.时薪 * 表现 * 熟练.倍率 * 折扣));
  // 熟练度按表现涨，玩得差也涨，只是少。一局最多 8 点。
  const 熟练变化 = Math.max(1, Math.round((参数.得分 / 100) * 8));
  return {
    收入,
    表现倍率: 表现,
    熟练倍率: 熟练.倍率,
    疲劳折扣: 折扣,
    体能变化: -参数.原有体力消耗,
    熟练变化,
  };
}

